// ─── HELPERS ─────────────────────────────────────────────────────────────────
const fmt     = (n) => new Intl.NumberFormat("fr-FR", { style:"currency", currency:"EUR" }).format(n);
const fmtDate = (ts) => new Date(ts).toLocaleDateString("fr-FR", { day:"2-digit", month:"short", hour:"2-digit", minute:"2-digit" });
const balance = (txs) => txs.reduce((a,t) => t.type==="contribution" ? a+t.amount : a-t.amount, 0);

// ─── AVATAR ──────────────────────────────────────────────────────────────────
function CharAvatar({ char, size = 56 }) {
  const img = REAL_IMGS[char.id];
  return (
    <div style={{
      width: size, height: size,
      borderRadius: size * 0.18,
      overflow: "hidden",
      border: `2.5px solid ${char.body}`,
      boxShadow: `0 3px 10px ${char.body}44`,
      flexShrink: 0,
      background: "#f8f8f8",
    }}>
      <img src={img} alt={char.name}
        style={{ width:"100%", height:"100%", objectFit:"cover", objectPosition:"top center", display:"block" }} />
    </div>
  );
}

