// ─── TX ITEM ─────────────────────────────────────────────────────────────────
function TxItem({ tx }) {
  const char = CHARACTERS.find(c => c.id === tx.character_id);
  const ded  = DEDICATIONS.find(d => d.id === tx.dedication_type);
  return (
    <div className="tx">
      {tx.type === "contribution" && char
        ? <CharAvatar char={char} size={42} />
        : <div style={{ fontSize:"1.6rem", width:42, textAlign:"center" }}>🍽️</div>
      }
      <div className="tx-info">
        <div className="tx-name">{tx.type==="expense" ? tx.description : (char?.name || "Contribution")}</div>
        {tx.dedication_type && tx.dedication_type !== "none" && ded && (
          <div className="tx-ded">
            <span className="tx-ded-heb">{ded.hebrew}</span>{tx.dedication_name}
          </div>
        )}
        <div className="tx-date">{fmtDate(tx.timestamp)}</div>
      </div>
      <div className={`tx-amt ${tx.type}`}>
        {tx.type==="contribution" ? "+" : "−"}{fmt(tx.amount)}
      </div>
    </div>
  );
}

// ─── HOME ────────────────────────────────────────────────────────────────────
function HomeView({ data, bal, onContrib, onHistory, onAdmin }) {
  const contribs = data.transactions.filter(t => t.type==="contribution");
  const expenses = data.transactions.filter(t => t.type==="expense");
  const totalIn  = contribs.reduce((a,t) => a+t.amount, 0);
  const totalOut = expenses.reduce((a,t) => a+t.amount, 0);
  const recent   = data.transactions.slice(0, 6);
  return (
    <>
      <div className="hdr">
        <img src={LOGO_SRC} alt="Tiferet Moché" className="hdr-logo" />
        <div className="hdr-name">Cagnotte Cours du Mardi</div>
        <div className="hdr-sub">Séouda hebdomadaire 🍽️</div>
      </div>
      <div className="bal">
        <div className="bal-lbl">Solde disponible</div>
        <div className={`bal-amt ${bal < 0 ? "neg" : ""}`}>{fmt(bal)}</div>
        <div className="bal-meta">
          <div className="bm"><div className="bm-val" style={{color:"#27ae60"}}>+{fmt(totalIn)}</div><div className="bm-lbl">Collecté</div></div>
          <div className="bm"><div className="bm-val" style={{color:"#e05555"}}>−{fmt(totalOut)}</div><div className="bm-lbl">Dépensé</div></div>
          <div className="bm"><div className="bm-val">{contribs.length}</div><div className="bm-lbl">Dons</div></div>
        </div>
      </div>
      <button className="btn btn-navy" onClick={onContrib}>🧱 Je contribue !</button>
      <button className="btn btn-blue" onClick={onHistory}>📜 Historique complet</button>
      <button className="btn btn-outline" onClick={onAdmin}>🔒 Espace gestionnaire</button>
      {recent.length > 0 && (<><div className="sec-title">Activité récente</div>{recent.map(tx => <TxItem key={tx.id} tx={tx} />)}</>)}
      {recent.length === 0 && (<div className="empty" style={{marginTop:28}}>Aucune contribution pour l'instant.<br />Soyez le premier ! 🙏</div>)}
    </>
  );
}

// ─── CONTRIBUTE ──────────────────────────────────────────────────────────────
function ContributeView({ data, onBack, onSuccess }) {
  const [step,    setStep]    = useState(1);
  const [selChar, setSelChar] = useState(null);
  const [dedType, setDedType] = useState("none");
  const [dedName, setDedName] = useState("");
  const [amount,  setAmount]  = useState("");
  const ded  = DEDICATIONS.find(d => d.id === dedType);
  const char = CHARACTERS.find(c => c.id === selChar);
  const goBack = () => step === 1 ? onBack() : setStep(s => s-1);
  const handleConfirm = () => {
    const val = parseFloat(amount);
    if (!val || val <= 0) return;
    onSuccess({ id:Date.now().toString(), type:"contribution", amount:val,
      character_id:selChar, dedication_type:dedType, dedication_name:dedName, timestamp:Date.now() });
  };
  return (
    <div className="wiz">
      <div className="wiz-hdr">
        <button className="back" onClick={goBack}>←</button>
        <div className="wiz-title">{["","Choisis ton personnage","Dédicace","Payer via Revolut","Confirmation"][step]}</div>
      </div>
      <div className="steps">{[1,2,3,4].map(s => <div key={s} className={`step-bar ${s<=step?"on":""}`} />)}</div>

      {step===1 && (
        <>
          <div className="char-grid">
            {CHARACTERS.map(c => (
              <div key={c.id} className={`char-card ${selChar===c.id?"sel":""}`} onClick={() => setSelChar(c.id)}>
                <img src={REAL_IMGS[c.id]} alt={c.name} className="char-photo" style={{border:`2px solid ${c.body}`}} />
                <div className="char-card-name">{c.name}</div>
              </div>
            ))}
          </div>
          <button className="btn btn-navy" disabled={!selChar} onClick={() => setStep(2)}>Continuer →</button>
        </>
      )}

      {step===2 && (
        <>
          {DEDICATIONS.map(d => (
            <div key={d.id} className={`ded-opt ${dedType===d.id?"sel":""}`} onClick={() => setDedType(d.id)}>
              <span className="ded-lbl">{d.label}</span>
              {d.hebrew && <span className="ded-heb">{d.hebrew}</span>}
            </div>
          ))}
          {dedType !== "none" && (
            <input className="field" style={{marginTop:10}}
              placeholder={ded?.placeholder || "Pour qui ?"} value={dedName}
              onChange={e => setDedName(e.target.value)} />
          )}
          <button className="btn btn-navy" style={{marginTop:8}} onClick={() => setStep(3)}>Continuer →</button>
        </>
      )}

      {step===3 && (
        <>
          <div className="qr-zone">
            {data.revolut_url ? (
              <>
                <div className="qr-wrap">
                  <img src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(data.revolut_url)}&color=1e3a5f&bgcolor=ffffff&margin=0`}
                    alt="QR Revolut" width={200} height={200} style={{display:"block",borderRadius:4}} />
                </div>
                <div className="qr-note">Scannez le QR ou tapez le lien :</div>
                <a className="qr-link" href={data.revolut_url} target="_blank" rel="noreferrer">{data.revolut_url}</a>
              </>
            ) : (
              <div style={{padding:"18px",background:"#edf2ff",border:"2px solid #dde8ff",borderRadius:14,color:"#7a90b8",marginBottom:16,lineHeight:1.5,fontWeight:600}}>
                ⚠️ Lien Revolut non configuré. Contactez le gestionnaire.
              </div>
            )}
          </div>
          <p style={{fontSize:".85rem",color:"#7a90b8",marginBottom:14,textAlign:"center",fontWeight:700}}>Après votre virement, saisissez le montant :</p>
          <div className="amt-row">
            <span className="amt-sym">€</span>
            <input type="number" min="0" step="0.5" className="amt-input"
              placeholder="0" value={amount} onChange={e => setAmount(e.target.value)} />
          </div>
          <button className="btn btn-navy" disabled={!amount || parseFloat(amount)<=0} onClick={() => setStep(4)}>J'ai payé ✓</button>
        </>
      )}

      {step===4 && (
        <>
          <div className="cf-card">
            <div style={{display:"flex",justifyContent:"center"}}>
              {char && <CharAvatar char={char} size={90} />}
            </div>
            <div className="cf-name">{char?.name}</div>
            <div className="cf-amt">+{fmt(parseFloat(amount))}</div>
            {dedType !== "none" && ded && (
              <div style={{marginTop:8}}>
                <span className="cf-ded-heb">{ded.hebrew}</span>
                {dedName && <span className="cf-ded-name">{dedName}</span>}
              </div>
            )}
            <div className="cf-bless">Que ce don soit une bénédiction pour toute la communauté 🤍</div>
          </div>
          <button className="btn btn-navy" onClick={handleConfirm}>✅ Valider et enregistrer</button>
        </>
      )}
    </div>
  );
}

// ─── HISTORY ─────────────────────────────────────────────────────────────────
function HistoryView({ transactions, onBack }) {
  return (
    <div className="wiz">
      <div className="wiz-hdr">
        <button className="back" onClick={onBack}>←</button>
        <div className="wiz-title">Historique complet</div>
      </div>
      {transactions.length === 0
        ? <div className="empty">Aucune transaction</div>
        : transactions.map(tx => <TxItem key={tx.id} tx={tx} />)
      }
    </div>
  );
}

// ─── ADMIN ───────────────────────────────────────────────────────────────────
const SUPER_ADMIN = "Yadmin"; // Code super-admin permanent — ne jamais modifier

function AdminView({ data, onBack, onUpdate }) {
  const [auth,        setAuth]        = useState(false);
  const [isSuperAdmin,setIsSuperAdmin]= useState(false);
  const [pwd,         setPwd]         = useState("");
  const [err,         setErr]         = useState("");
  const [expAmt,      setExpAmt]      = useState("");
  const [expDesc,     setExpDesc]     = useState("");
  const [revUrl,      setRevUrl]      = useState(data.revolut_url || "");
  const [newPwd,      setNewPwd]      = useState("");
  const [success,     setSuccess]     = useState("");
  const [confirmReset,setConfirmReset]= useState(false);
  const [confirmDel,  setConfirmDel]  = useState(null); // id de la transaction à supprimer

  const flash = (m) => { setSuccess(m); setTimeout(() => setSuccess(""), 2500); };

  const tryLogin = () => {
    if (pwd === SUPER_ADMIN) {
      setAuth(true); setIsSuperAdmin(true); setErr("");
    } else if (pwd === data.admin_password) {
      setAuth(true); setIsSuperAdmin(false); setErr("");
    } else {
      setErr("Mot de passe incorrect ❌");
    }
  };

  const addExpense = () => {
    const val = parseFloat(expAmt);
    if (!val || val<=0 || !expDesc.trim()) return;
    onUpdate(prev => ({ ...prev, transactions:[{id:Date.now().toString(),type:"expense",amount:val,description:expDesc.trim(),timestamp:Date.now()},...prev.transactions] }));
    setExpAmt(""); setExpDesc(""); flash("Dépense enregistrée ✓");
  };

  const saveConfig = () => {
    onUpdate(prev => ({ ...prev, revolut_url:revUrl.trim(), ...(newPwd.trim()? {admin_password:newPwd.trim()} :{}) }));
    setNewPwd(""); flash("Configuration sauvegardée ✓");
  };

  const doReset = () => {
    onUpdate(prev => ({ ...prev, transactions: [] }));
    setConfirmReset(false);
    flash("Cagnotte remise à zéro ✓");
  };

  const deleteTransaction = (id) => {
    onUpdate(prev => ({ ...prev, transactions: prev.transactions.filter(t => t.id !== id) }));
    setConfirmDel(null);
    flash("Saisie supprimée ✓");
  };

  return (
    <div className="wiz">
      <div className="wiz-hdr">
        <button className="back" onClick={onBack}>←</button>
        <div className="wiz-title">
          🔒 Espace gestionnaire
          {isSuperAdmin && <span style={{fontSize:".7rem",marginLeft:8,color:"#c9a800",fontFamily:"'Nunito',sans-serif",fontWeight:800}}>SUPER ADMIN</span>}
        </div>
      </div>

      {!auth ? (
        <>
          <p style={{fontSize:".88rem",color:"#7a90b8",marginBottom:16,lineHeight:1.5,fontWeight:600}}>
            Réservé au gestionnaire.<br/>Mot de passe par défaut : <strong style={{color:"#2461c5"}}>Torah1</strong>
          </p>
          <input type="password" className="field" placeholder="Mot de passe"
            value={pwd} onChange={e => setPwd(e.target.value)}
            onKeyDown={e => e.key==="Enter" && tryLogin()} />
          {err && <div className="err">{err}</div>}
          <button className="btn btn-navy" onClick={tryLogin}>Accéder</button>
        </>
      ) : (
        <>
          {success && <div className="success">{success}</div>}

          <div className="adm-sec">
            <div className="adm-sec-title">📋 Enregistrer une dépense</div>
            <input type="number" className="field" placeholder="Montant (€)" value={expAmt} onChange={e => setExpAmt(e.target.value)} />
            <input className="field" placeholder="Description (ex : Courses mardi soir)" value={expDesc} onChange={e => setExpDesc(e.target.value)} />
            <button className="btn-adm" style={{opacity:expAmt&&expDesc?1:.35}} onClick={addExpense}>Enregistrer la dépense</button>
          </div>

          <div className="adm-sec">
            <div className="adm-sec-title">⚙️ Configuration</div>
            <input className="field" placeholder="Lien Revolut (https://revolut.me/...)" value={revUrl} onChange={e => setRevUrl(e.target.value)} />
            <input type="password" className="field" placeholder="Nouveau mot de passe (vide = inchangé)" value={newPwd} onChange={e => setNewPwd(e.target.value)} />
            <button className="btn-adm" onClick={saveConfig}>💾 Sauvegarder</button>
          </div>

          <div className="adm-sec">
            <div className="adm-sec-title">🗑️ Corriger une saisie</div>
            <p style={{fontSize:".82rem",color:"#7a90b8",marginBottom:12,lineHeight:1.45,fontWeight:600}}>
              Supprime un don ou une dépense saisi par erreur. Le solde se recalcule automatiquement.
            </p>
            {data.transactions.length === 0 ? (
              <p style={{fontSize:".85rem",color:"#9aa8c4",textAlign:"center",padding:"8px 0"}}>Aucune saisie pour le moment.</p>
            ) : (
              <div style={{display:"flex",flexDirection:"column",gap:8}}>
                {data.transactions.map(tx => {
                  const char  = CHARACTERS.find(c => c.id === tx.character_id);
                  const label = tx.type === "expense" ? tx.description : (char?.name || "Contribution");
                  const sign  = tx.type === "contribution" ? "+" : "−";
                  return (
                    <div key={tx.id} style={{border:"1px solid #edf2ff",borderRadius:12,padding:"10px 12px",background:"#fbfcff"}}>
                      <div style={{display:"flex",alignItems:"center",gap:10}}>
                        <div style={{fontSize:"1.3rem"}}>{tx.type==="expense" ? "🍽️" : "🪙"}</div>
                        <div style={{flex:1,minWidth:0}}>
                          <div style={{fontWeight:700,color:"#1e3a5f",fontSize:".92rem",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{label}</div>
                          <div style={{fontSize:".72rem",color:"#9aa8c4"}}>{fmtDate(tx.timestamp)}</div>
                        </div>
                        <div style={{fontWeight:800,fontSize:".92rem",color:tx.type==="contribution" ? "#2461c5" : "#e05555"}}>
                          {sign}{fmt(tx.amount)}
                        </div>
                        {confirmDel !== tx.id && (
                          <button onClick={() => setConfirmDel(tx.id)}
                            style={{border:"none",background:"transparent",cursor:"pointer",fontSize:"1.1rem",padding:"4px 6px"}}
                            title="Supprimer cette saisie">🗑️</button>
                        )}
                      </div>
                      {confirmDel === tx.id && (
                        <div style={{marginTop:10,background:"#fff5f5",border:"2px solid #e05555",borderRadius:10,padding:12}}>
                          <p style={{fontSize:".85rem",fontWeight:700,color:"#e05555",marginBottom:10,textAlign:"center"}}>
                            Supprimer « {label} » · {sign}{fmt(tx.amount)} ?
                          </p>
                          <div style={{display:"flex",gap:8}}>
                            <button className="btn-adm" style={{flex:1,background:"#e05555",margin:0}} onClick={() => deleteTransaction(tx.id)}>
                              Supprimer
                            </button>
                            <button className="btn-adm" style={{flex:1,background:"#7a90b8",margin:0}} onClick={() => setConfirmDel(null)}>
                              Annuler
                            </button>
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          <div className="adm-sec">
            <div className="adm-sec-title" style={{color:"#e05555"}}>🗑️ Remise à zéro</div>
            {!confirmReset ? (
              <button className="btn-adm" style={{background:"#e05555",boxShadow:"0 3px 10px rgba(224,85,85,.25)"}}
                onClick={() => setConfirmReset(true)}>
                Vider l'historique et remettre à zéro
              </button>
            ) : (
              <div style={{background:"#fff5f5",border:"2px solid #e05555",borderRadius:14,padding:16}}>
                <p style={{fontSize:".9rem",fontWeight:700,color:"#e05555",marginBottom:14,textAlign:"center"}}>
                  ⚠️ Toutes les transactions seront supprimées.<br/>Cette action est irréversible.
                </p>
                <div style={{display:"flex",gap:10}}>
                  <button className="btn-adm" style={{flex:1,background:"#e05555",margin:0}} onClick={doReset}>
                    Confirmer
                  </button>
                  <button className="btn-adm" style={{flex:1,background:"#7a90b8",margin:0}} onClick={() => setConfirmReset(false)}>
                    Annuler
                  </button>
                </div>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

// ─── ROOT ────────────────────────────────────────────────────────────────────
export default function App() {
  const [data,    setData]    = useState(null);
  const [view,    setView]    = useState("home");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const DEFAULT = { transactions: [], revolut_url: "", admin_password: "Torah1" };

    // Timeout de secours — affiche l'app après 3s max même si Firebase ne répond pas
    const timeout = setTimeout(() => {
      setData(prev => prev ?? DEFAULT);
      setLoading(false);
    }, 3000);

    // Abonnement temps réel Firebase
    let unsub = () => {};
    try {
      unsub = subscribeData((d) => {
        clearTimeout(timeout);
        setData(d);
        setLoading(false);
      });
    } catch(e) {
      console.warn("Firebase non configuré, mode local activé");
    }

    // Chargement initial
    loadData()
      .then(d => {
        clearTimeout(timeout);
        setData(prev => prev ?? d);
        setLoading(false);
      })
      .catch(() => {
        clearTimeout(timeout);
        setData(prev => prev ?? DEFAULT);
        setLoading(false);
      });

    return () => { clearTimeout(timeout); unsub(); };
  }, []);

  const updateData = useCallback((updater) => {
    setData(prev => {
      const next = typeof updater === "function" ? updater(prev) : updater;
      saveData(next);
      return next;
    });
  }, []);

  if (loading || !data)
    return (
      <div style={{display:"flex",alignItems:"center",justifyContent:"center",
        height:"100vh",background:"#edf2ff",
        fontFamily:"'Fredoka One',sans-serif",fontSize:"1.4rem",color:"#1e3a5f"}}>
        🏫 Chargement…
      </div>
    );

  const bal = balance(data.transactions);

  return (
    <>
      <style>{CSS}</style>
      <div className="app">
        {view==="home"       && <HomeView data={data} bal={bal} onContrib={()=>setView("contribute")} onHistory={()=>setView("history")} onAdmin={()=>setView("admin")} />}
        {view==="contribute" && <ContributeView data={data} onBack={()=>setView("home")} onSuccess={tx=>{updateData(p=>({...p,transactions:[tx,...p.transactions]}));setView("home");}} />}
        {view==="history"    && <HistoryView transactions={data.transactions} onBack={()=>setView("home")} />}
        {view==="admin"      && <AdminView data={data} onBack={()=>setView("home")} onUpdate={updateData} />}
      </div>
    </>
  );
}
